From 629e2eff0ac95e2a75630b5c563bbe64e30cc957 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 17:46:18 +0100
Subject: [PATCH] lockscreen: clear the password when left idle

A password typed but never submitted stayed in the field forever, and it
even kept the prompt from fading out while the pointer was over it. Now
the prompt fades out after the usual idle time and clears the password.

BUG: 434321
---
 desktoppackage/contents/lockscreen/LockScreenUi.qml | 11 ++++++++++-
 1 file changed, 10 insertions(+), 1 deletion(-)

diff --git a/desktoppackage/contents/lockscreen/LockScreenUi.qml b/desktoppackage/contents/lockscreen/LockScreenUi.qml
index 065a33c131..d16bca1438 100644
--- a/desktoppackage/contents/lockscreen/LockScreenUi.qml
+++ b/desktoppackage/contents/lockscreen/LockScreenUi.qml
@@ -140,7 +140,7 @@ Item {

         property bool uiVisible: false
         property bool seenPositionChange: false
-        property bool blockUI: containsMouse && (mainStack.depth > 1 || mainBlock.mainPasswordBox.text.length > 0 || Keyboards.KWinVirtualKeyboard.visible)
+        property bool blockUI: containsMouse && (mainStack.depth > 1 || Keyboards.KWinVirtualKeyboard.visible)

         x: parent.x
         y: parent.y
@@ -214,6 +214,15 @@ Item {
                 if (!lockScreenRoot.blockUI) {
                     mainBlock.mainPasswordBox.showPassword = false;
                     lockScreenRoot.uiVisible = false;
+                    root.clearPassword();
+                }
+            }
+        }
+        Connections {
+            target: mainBlock.mainPasswordBox
+            function onTextChanged() {
+                if (lockScreenRoot.uiVisible && !lockScreenRoot.blockUI) {
+                    fadeoutTimer.restart();
                 }
             }
         }
-- 
